import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import { Vibration } from 'react-native';

let player: AudioPlayer | null = null;

/**
 * Starts a looping car-horn alarm (generated by scripts/make-horn.js) plus continuous
 * vibration. Keeps going (including in the background) until stopAlarm() is called.
 * Plays even when the iOS silent switch is on.
 *
 * Note: apps can't raise the system volume. The horn plays at full app volume
 * relative to the media volume, so keep media volume up while scanning.
 */
export async function startAlarm() {
  if (player) return;
  await setAudioModeAsync({
    playsInSilentMode: true,
    shouldPlayInBackground: true,
    interruptionMode: 'doNotMix',
  });
  player = createAudioPlayer(require('../../assets/sounds/alarm.wav'));
  player.loop = true;
  player.volume = 1.0;
  player.play();
  Vibration.vibrate([0, 800, 300], true);
}

export function stopAlarm() {
  Vibration.cancel();
  if (player) {
    player.pause();
    player.remove();
    player = null;
  }
}
